 10→/**
 11→ * Contract: Order-preserving encryption using the Boldyreva scheme with hypergeometric sampling.
 12→ * Stateless and key-only — no mutable state required. Maps a plaintext domain {@code [1..M]} to a
 13→ * ciphertext range {@code [1..N]} where {@code N >> M}, preserving ordering: if {@code a < b} then
 14→ * {@code encrypt(a) < encrypt(b)}.
 15→ *
 16→ * <p>
 17→ * Uses recursive bisection with key-seeded pseudorandom coin from AES-based PRF to sample from the
 18→ * hypergeometric distribution, mapping each plaintext to a unique ciphertext preserving order.
 19→ *
 20→ * <p>
 21→ * Governed by: .kb/algorithms/encryption/searchable-encryption-schemes.md
 22→ */
 23→public final class BoldyrevaOpeEncryptor {
 24→
 25→    private static final int MAX_RECURSION_DEPTH = 128;
 26→
 27→    private final byte[] keyBytes;
 28→    private final long domainSize;
 29→    private final long rangeSize;
 30→
 31→    /**
 32→     * Creates a Boldyreva OPE encryptor with the given key and domain/range configuration.
 33→     *
 34→     * @param keyHolder the key holder providing key material
 35→     * @param domainSize the plaintext domain size M (values in [1..M])
 36→     * @param rangeSize the ciphertext range size N (values in [1..N], must be {@code > domainSize})
 37→     * @throws IllegalArgumentException if rangeSize is not greater than domainSize, or domainSize <
 38→     *             1
 39→     */
 40→    public BoldyrevaOpeEncryptor(EncryptionKeyHolder keyHolder, long domainSize, long rangeSize) {
 41→        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
 42→        if (domainSize < 1) {
 43→            throw new IllegalArgumentException("domainSize must be >= 1, got " + domainSize);
 44→        }
 45→        if (rangeSize <= domainSize) {
 46→            throw new IllegalArgumentException("rangeSize must be > domainSize, got rangeSize="
 47→                    + rangeSize + " domainSize=" + domainSize);
 48→        }
 49→        this.keyBytes = keyHolder.getKeyBytes();
 50→        this.domainSize = domainSize;
 51→        this.rangeSize = rangeSize;
 52→    }
 53→
 54→    /**
 55→     * Encrypts a plaintext value, preserving order.
 56→     *
 57→     * @param plaintext the value to encrypt; must be in {@code [1..domainSize]}
 58→     * @return the encrypted value in {@code [1..rangeSize]}
 59→     * @throws IllegalArgumentException if plaintext is out of domain bounds
 60→     */
 61→    public long encrypt(long plaintext) {
 62→        if (plaintext < 1 || plaintext > domainSize) {
 63→            throw new IllegalArgumentException(
 64→                    "Plaintext must be in [1.." + domainSize + "], got " + plaintext);
 65→        }
 66→        return encryptRecursive(plaintext, 1, domainSize, 1, rangeSize, 0);
 67→    }
 68→
 69→    /**
 70→     * Decrypts a ciphertext value via binary search.
 71→     *
 72→     * @param ciphertext the encrypted value; must be in {@code [1..rangeSize]}
 73→     * @return the original plaintext in {@code [1..domainSize]}
 74→     * @throws IllegalArgumentException if ciphertext is out of range bounds
 75→     */
 76→    public long decrypt(long ciphertext) {
 77→        if (ciphertext < 1 || ciphertext > rangeSize) {
 78→            throw new IllegalArgumentException(
 79→                    "Ciphertext must be in [1.." + rangeSize + "], got " + ciphertext);
 80→        }
 81→        // Binary search: find plaintext p such that encrypt(p) == ciphertext
 82→        long lo = 1;
 83→        long hi = domainSize;
 84→        while (lo <= hi) {
 85→            final long mid = lo + (hi - lo) / 2;
 86→            final long enc = encrypt(mid);
 87→            if (enc == ciphertext) {
 88→                return mid;
 89→            } else if (enc < ciphertext) {
 90→                lo = mid + 1;
 91→            } else {
 92→                hi = mid - 1;
 93→            }
 94→        }
 95→        throw new IllegalArgumentException("No plaintext maps to ciphertext " + ciphertext
 96→                + " in the configured domain/range");
 97→    }
 98→
 99→    // ── Recursive bisection (Boldyreva lazy-sample) ─────────────────────────
100→
101→    /**
102→     * Recursively maps plaintext m in [dLo..dHi] to ciphertext in [rLo..rHi]. At each step, pick
103→     * midpoint of the range, sample a "coin" from HG distribution to decide how many domain values
104→     * fall in the left half, then recurse into the appropriate half.
105→     */
106→    private long encryptRecursive(long plaintext, long dLo, long dHi, long rLo, long rHi,
107→            int depth) {
108→        assert dLo <= dHi : "domain lo > hi";
109→        assert rLo <= rHi : "range lo > hi";
110→        assert depth <= MAX_RECURSION_DEPTH : "max recursion depth exceeded at " + depth;
111→
112→        final long dSize = dHi - dLo + 1;
113→        final long rSize = rHi - rLo + 1;
114→
115→        if (dSize == 1) {
116→            // Single domain value — map to midpoint of remaining range
117→            return rLo + rSize / 2;
118→        }
119→
120→        // Midpoint of range
121→        final long rMid = rLo + (rSize - 1) / 2;
122→        final long rLeftSize = rMid - rLo + 1;
123→
124→        // Sample how many domain values land in the left half [rLo..rMid]
125→        // using HG(rSize, dSize, rLeftSize) seeded by key + (dLo, dHi, rLo, rHi)
126→        final long dLeftCount = sampleHypergeometric(rSize, dSize, rLeftSize, dLo, dHi, rLo, rHi);
127→
128→        if (plaintext <= dLo + dLeftCount - 1) {
129→            // Plaintext is in the left partition
130→            return encryptRecursive(plaintext, dLo, dLo + dLeftCount - 1, rLo, rMid, depth + 1);
131→        } else {
132→            // Plaintext is in the right partition
133→            return encryptRecursive(plaintext, dLo + dLeftCount, dHi, rMid + 1, rHi, depth + 1);
134→        }
135→    }
136→
137→    /**
138→     * Samples from the hypergeometric distribution HG(N, K, n) using an AES-based PRF coin.
139→     *
140→     * Population N = rangeSegmentSize, success states K = domainSegmentSize, draws n =
141→     * leftRangeSize.
142→     *
143→     * Returns the number of domain values that fall in the left range partition. Uses the
144→     * sequential sampling algorithm (Fisher-Yates style).
145→     */
146→    private long sampleHypergeometric(long popN, long succK, long draws, long dLo, long dHi,
147→            long rLo, long rHi) {
148→        assert popN > 0 : "population must be positive";
149→        assert succK >= 0 && succK <= popN : "succK out of bounds";
150→        assert draws >= 0 && draws <= popN : "draws out of bounds";
151→
152→        // Derive a deterministic seed for this particular node from key + parameters
153→        final long nodeSeed = prfSeed(dLo, dHi, rLo, rHi);
154→
155→        // Sequential sampling: iterate through draws, each time flipping a coin
156→        long population = popN;
157→        long successes = succK;
158→        long selected = 0;
159→        long coinState = nodeSeed;
160→
161→        for (long i = 0; i < draws && successes > 0; i++) {
162→            // Probability of selecting a success: successes / population
163→            // Use PRF coin to decide
164→            coinState = prfNext(coinState, i);
165→            final double threshold = (double) successes / (double) population;
166→            final double coin = pseudoUniform(coinState);
167→
168→            if (coin < threshold) {
169→                selected++;
170→                successes--;
171→            }
172→            population--;
173→        }
174→
175→        return selected;
176→    }
177→
178→    /**
179→     * Derives a deterministic seed from the key and node parameters using AES encryption.
180→     */
181→    private long prfSeed(long dLo, long dHi, long rLo, long rHi) {
182→        try {
183→            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
184→            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, 0,
185→                    Math.min(keyBytes.length, 32), "AES");
186→            aes.init(Cipher.ENCRYPT_MODE, keySpec);
187→
188→            final ByteBuffer buf = ByteBuffer.allocate(16);
189→            buf.putInt((int) (dLo ^ (dLo >>> 32)));
190→            buf.putInt((int) (dHi ^ (dHi >>> 32)));
191→            buf.putInt((int) (rLo ^ (rLo >>> 32)));
192→            buf.putInt((int) (rHi ^ (rHi >>> 32)));
193→
194→            final byte[] encrypted = aes.doFinal(buf.array());
195→            return ByteBuffer.wrap(encrypted).getLong();
196→        } catch (GeneralSecurityException e) {
197→            throw new IllegalStateException("AES PRF failed", e);
198→        }
199→    }
200→
201→    /**
202→     * Derives the next PRF state from current state and iteration.
203→     */
204→    private long prfNext(long state, long iteration) {
205→        try {
206→            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
207→            final SecretKeySpec keySpec = new SecretKeySpec(keyBytes, 0,
208→                    Math.min(keyBytes.length, 32), "AES");
209→            aes.init(Cipher.ENCRYPT_MODE, keySpec);
210→
211→            final ByteBuffer buf = ByteBuffer.allocate(16);
212→            buf.putLong(state);
213→            buf.putLong(iteration);
214→
215→            final byte[] encrypted = aes.doFinal(buf.array());
216→            return ByteBuffer.wrap(encrypted).getLong();
217→        } catch (GeneralSecurityException e) {
218→            throw new IllegalStateException("AES PRF failed", e);
219→        }
220→    }
221→
222→    /**
223→     * Maps a long to a pseudo-uniform double in [0, 1).
224→     */
225→    private static double pseudoUniform(long value) {
226→        return (double) (value >>> 1) / (double) Long.MAX_VALUE;
227→    }
228→}
